"""Build a training set from real + pseudo-labelled images, with weak-class oversampling.

    python src/build_pl_dataset.py --tool-dup 3 --pt-dup 1 --db-dup 1

Output: data/yolo_pl/ with images/{train,val}, labels/{train,val}, data.yaml.

* real train images are hard-linked from data/yolo (no extra disk)
* pseudo-labelled test images come from data/pseudo (generated by make_pseudo.py)
* images containing tool / pressuretank / drinkbottle are duplicated N extra times,
  which is the cheapest way to raise the gradient share of the weak classes
* val is copied unchanged, so every number stays comparable with A/B/C/D

Duplicates get a distinct stem suffix; Ultralytics treats them as ordinary images.
"""

from __future__ import annotations

import argparse
import os
import shutil
import sys
from collections import Counter
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from classes import CLASSES, NAME_TO_ID, NUM_CLASSES  # noqa: E402

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "data" / "yolo"
PSEUDO = ROOT / "data" / "pseudo"
OUT = ROOT / "data" / "yolo_pl"

# class -> number of EXTRA copies to add
DUP_CLASSES = {"tool": "tool-dup", "pressuretank": "pt-dup", "drinkbottle": "db-dup"}


def link(src: Path, dst: Path) -> None:
    if dst.exists():
        return
    try:
        os.link(src, dst)
    except OSError:
        shutil.copyfile(src, dst)


def classes_in(label_path: Path) -> set[str]:
    ids = set()
    if label_path.exists():
        for line in label_path.read_text(encoding="utf-8").splitlines():
            if line.strip():
                ids.add(int(float(line.split()[0])))
    return {CLASSES[i] for i in ids if 0 <= i < len(CLASSES)}


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--tool-dup", type=int, default=3)
    ap.add_argument("--pt-dup", type=int, default=1)
    ap.add_argument("--db-dup", type=int, default=1)
    ap.add_argument("--use-pseudo", type=int, default=1)
    ap.add_argument("--max-pseudo", type=int, default=5000)
    ap.add_argument("--clean", action="store_true")
    args = ap.parse_args()

    dups = {"tool": args.tool_dup, "pressuretank": args.pt_dup, "drinkbottle": args.db_dup}

    if args.clean and OUT.exists():
        shutil.rmtree(OUT)
    for sub in ("images/train", "images/val", "labels/train", "labels/val"):
        (OUT / sub).mkdir(parents=True, exist_ok=True)

    counts = Counter()
    box_counts: Counter[str] = Counter()

    # ---------------- real train + oversampled duplicates ----------------
    real_imgs = sorted((SRC / "images" / "train").glob("*.jpg"))
    for img in real_imgs:
        stem = img.stem
        lbl = SRC / "labels" / "train" / f"{stem}.txt"
        link(img, OUT / "images" / "train" / img.name)
        link(lbl, OUT / "labels" / "train" / f"{stem}.txt")
        counts["real"] += 1
        present = classes_in(lbl)
        for cls, times in dups.items():
            if cls in present:
                for k in range(1, times + 1):
                    link(img, OUT / "images" / "train" / f"{stem}_dup{k}.jpg")
                    link(lbl, OUT / "labels" / "train" / f"{stem}_dup{k}.txt")
                    counts[f"dup_{cls}"] += 1

    # ---------------- pseudo labels ----------------
    if args.use_pseudo and PSEUDO.exists():
        pseudo_imgs = sorted((PSEUDO / "images").glob("*.jpg"))[: args.max_pseudo]
        for img in pseudo_imgs:
            lbl = PSEUDO / "labels" / f"{img.stem}.txt"
            if not lbl.exists() or lbl.stat().st_size == 0:
                continue
            link(img, OUT / "images" / "train" / f"pl_{img.name}")
            link(lbl, OUT / "labels" / "train" / f"pl_{img.stem}.txt")
            counts["pseudo"] += 1

    # ---------------- val, unchanged ----------------
    for img in sorted((SRC / "images" / "val").glob("*.jpg")):
        lbl = SRC / "labels" / "val" / f"{img.stem}.txt"
        link(img, OUT / "images" / "val" / img.name)
        link(lbl, OUT / "labels" / "val" / f"{img.stem}.txt")

    # effective class distribution in the new train split
    for lbl in (OUT / "labels" / "train").glob("*.txt"):
        for line in lbl.read_text(encoding="utf-8").splitlines():
            if line.strip():
                box_counts[CLASSES[int(float(line.split()[0]))]] += 1

    (OUT / "data.yaml").write_text(
        f"path: {OUT.as_posix()}\n"
        "train: images/train\n"
        "val: images/val\n"
        f"nc: {NUM_CLASSES}\n"
        "names:\n" + "".join(f"  {i}: {n}\n" for i, n in enumerate(CLASSES)),
        encoding="utf-8",
    )

    n_train = len(list((OUT / "images" / "train").glob("*.jpg")))
    n_val = len(list((OUT / "images" / "val").glob("*.jpg")))
    print(f"train images : {n_train}")
    for k, v in sorted(counts.items()):
        print(f"  {k:<12}{v:>7}")
    print(f"val images   : {n_val}  (unchanged)")
    print()
    print(f"{'class':<14}{'boxes (train)':>15}{'was':>8}")
    before = {"drinkbottle": 1479, "glassbottle": 8736, "knife": 384, "laptop": 362,
              "metalbottle": 1134, "pressuretank": 670, "tool": 126, "umbrella": 573}
    for cls in CLASSES:
        print(f"{cls:<14}{box_counts[cls]:>15}{before[cls]:>8}")
    print(f"\n-> {OUT}  ({OUT / 'data.yaml'})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
